    Bug 1924630 - Port bug 1917901: Use return value of nsIStreamListener.onDataAvailable. rs=bustage-fix

diff --git a/mailnews/imap/src/nsImapProtocol.cpp b/mailnews/imap/src/nsImapProtocol.cpp
index 8be064640f7..81d01f3d7a4 100644
--- a/mailnews/imap/src/nsImapProtocol.cpp
+++ b/mailnews/imap/src/nsImapProtocol.cpp
@@ -3704,8 +3704,9 @@ void nsImapProtocol::PostLineDownLoadEvent(const char* line,
         NS_ASSERTION(count == byteCount,
                      "IMAP channel pipe couldn't buffer entire write");
         if (NS_SUCCEEDED(rv)) {
-          m_channelListener->OnDataAvailable(m_mockChannel,
-                                             m_channelInputStream, 0, count);
+          rv = m_channelListener->OnDataAvailable(
+              m_mockChannel, m_channelInputStream, 0, count);
+          NS_ENSURE_SUCCESS_VOID(rv);
         }
         // else some sort of explosion?
       }
diff --git a/mailnews/mime/emitters/nsMimeBaseEmitter.cpp b/mailnews/mime/emitters/nsMimeBaseEmitter.cpp
index 118182deea6..be573bf31de 100644
--- a/mailnews/mime/emitters/nsMimeBaseEmitter.cpp
+++ b/mailnews/mime/emitters/nsMimeBaseEmitter.cpp
@@ -411,8 +411,9 @@ nsresult nsMimeBaseEmitter::WriteHelper(const nsACString& buf,
     uint64_t avail;
     rv = mInputStream->Available(&avail);
     if (NS_SUCCEEDED(rv) && avail) {
-      mOutListener->OnDataAvailable(mChannel, mInputStream, 0,
-                                    std::min(avail, uint64_t(PR_UINT32_MAX)));
+      rv = mOutListener->OnDataAvailable(
+          mChannel, mInputStream, 0, std::min(avail, uint64_t(PR_UINT32_MAX)));
+      NS_ENSURE_SUCCESS(rv, rv);

       // try writing again...
       rv = mOutStream->Write(buf.BeginReading(), buf.Length(), countWritten);
@@ -936,13 +937,13 @@ nsMimeBaseEmitter::Complete() {
     mozilla::DebugOnly<nsresult> rv2 = mInputStream->Available(&bytesInStream);
     NS_ASSERTION(NS_SUCCEEDED(rv2), "Available failed");
     if (bytesInStream) {
-      mOutListener->OnDataAvailable(
+      rv = mOutListener->OnDataAvailable(
           mChannel, mInputStream, 0,
           std::min(bytesInStream, uint64_t(PR_UINT32_MAX)));
     }
   }

-  return NS_OK;
+  return rv;
 }

